package org.apache.commons.jxpath.ri.model.jdom;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.jdom.JDOMAttributeIterator;
import org.apache.commons.jxpath.ri.model.jdom.NodePointer;
import org.apache.commons.jxpath.ri.model.jdom.QName;
import org.jdom.Attribute;
import org.jdom.Element;
import org.jdom.Namespace;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

public class JDOMAttributeIterator_setPosition_TriageGen1Test {

    private NodePointer mockParent;
    private QName mockName;
    private JDOMAttributeIterator iterator;

    @Before
    public void setUp() {
        mockParent = mock(NodePointer.class);
        mockName = mock(QName.class);
        iterator = new JDOMAttributeIterator(mockParent, mockName);
    }

    /**
     * Helper to set the private 'attributes' field via reflection to control test scenarios.
     */
    private void setAttributesField(JDOMAttributeIterator iterator, List<?> attributes) throws Exception {
        Field field = JDOMAttributeIterator.class.getDeclaredField("attributes");
        field.setAccessible(true);
        field.set(iterator, attributes);
    }

    @Test
    public void testSetPosition_AttributesNull() throws Exception {
        // Scenario: attributes is null
        setAttributesField(iterator, null);

        boolean result = iterator.setPosition(1);

        assertFalse("Should return false when attributes is null", result);
    }

    @Test
    public void testSetPosition_ValidPosition_LowerBound() throws Exception {
        // Scenario: position is exactly 1 (minimum valid)
        List<?> attributes = java.util.Arrays.asList("attr1", "attr2", "attr3");
        setAttributesField(iterator, attributes);

        boolean result = iterator.setPosition(1);

        assertTrue("Should return true for position 1", result);
        assertEquals("Position should be updated to 1", 1, iterator.getPosition());
    }

    @Test
    public void testSetPosition_ValidPosition_UpperBound() throws Exception {
        // Scenario: position is exactly attributes.size()
        List<?> attributes = java.util.Arrays.asList("attr1", "attr2", "attr3");
        setAttributesField(iterator, attributes);

        boolean result = iterator.setPosition(3);

        assertTrue("Should return true for position equal to size", result);
        assertEquals("Position should be updated to 3", 3, iterator.getPosition());
    }

    @Test
    public void testSetPosition_ValidPosition_Middle() throws Exception {
        // Scenario: position is in the middle
        List<?> attributes = java.util.Arrays.asList("attr1", "attr2", "attr3");
        setAttributesField(iterator, attributes);

        boolean result = iterator.setPosition(2);

        assertTrue("Should return true for position 2", result);
        assertEquals("Position should be updated to 2", 2, iterator.getPosition());
    }

    @Test
    public void testSetPosition_InvalidPosition_TooLow() throws Exception {
        // Scenario: position is less than 1
        List<?> attributes = java.util.Arrays.asList("attr1", "attr2");
        setAttributesField(iterator, attributes);

        boolean result = iterator.setPosition(0);

        assertFalse("Should return false for position < 1", result);
        assertEquals("Position should still be updated to 0 even if return is false", 0, iterator.getPosition());
    }

    @Test
    public void testSetPosition_InvalidPosition_TooHigh() throws Exception {
        // Scenario: position is greater than attributes.size()
        List<?> attributes = java.util.Arrays.asList("attr1", "attr2");
        setAttributesField(iterator, attributes);

        boolean result = iterator.setPosition(3);

        assertFalse("Should return false for position > size", result);
        assertEquals("Position should still be updated to 3 even if return is false", 3, iterator.getPosition());
    }

    @Test
    public void testSetPosition_EmptyAttributes_InvalidPosition() throws Exception {
        // Scenario: attributes list is empty
        List<?> attributes = java.util.Collections.emptyList();
        setAttributesField(iterator, attributes);

        // Any position will be invalid because 1 <= pos <= 0 is impossible
        boolean result = iterator.setPosition(1);

        assertFalse("Should return false when attributes list is empty", result);
    }
}
